// Build the SOP §4 employment-verification email (sent to prior-employer HR).
// Inbound payload (from Next.js fireOnboardingTemplate):
//   { onboarderId, template:'employment-verification', event, context: {
//     verification_id, company, hr_contact_name, hr_email,
//     full_name, role_title, onboarding_lead
//   } }

const body = ($input.first().json.body ?? $input.first().json);
const ctx  = body.context || {};
const company        = ctx.company          || 'your company';
const hrEmail        = ctx.hr_email         || body.to;
const hrName         = ctx.hr_contact_name  || 'HR Department';
const candidateName  = ctx.full_name        || 'the candidate';
const roleTitle      = ctx.role_title       || 'the role';
const onboardingLead = ctx.onboarding_lead  || 'Erich';

if (!hrEmail) {
  throw new Error('No hr_email on context — cannot send employment verification');
}

const subject = `Employment Verification Request for ${candidateName} | Romega Solutions`;
const body_ = `Hi ${hrName},

${candidateName} listed ${company} for the employment verification process for the ${roleTitle} role and they have given permission for this verification. We'd be grateful for your feedback.

If possible, please respond within 48 business hours, as delays may affect the candidate's onboarding application. Your verification will be kept confidential and used only for hiring purposes.

File format: please save your responses as a PDF (not Word) and attach it to your reply.

Thank you in advance for your assistance.

Cheers,
${onboardingLead}
Onboarding Lead, Romega Solutions`;

return [{ json: { to: hrEmail, subject, body: body_, onboarderId: body.onboarderId, verificationId: ctx.verification_id, template: 'employment-verification' } }];

const to = String($json.to || '').trim().toLowerCase();
const payload = ($('Webhook').first().json.body ?? $('Webhook').first().json);
const ccRecipient = String(payload.context?.onboarding_lead_email || payload.context?.requested_by_email || '').trim().toLowerCase();
const cc = ccRecipient && ccRecipient !== to ? ccRecipient : '';

return [{ json: { ...$json, cc } }];
